[tool-call run_code] {"timeoutMs": 300000, "code": "
const L: string[] = [];
L.push("$ErrorActionPreference = 'Continue'");
L.push("$ua = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Chrome/131 Mobile'");
L.push("$urls = @(");
L.push(" 'http://news.cnr.cn/native/gd/20260727/t20260727_527731759.shtml',");
L.push(" 'https://www.cssn.cn/skgz/bwyc/202604/t20260420_5980978.shtml',");
L.push(" 'https://legal.gmw.cn/2025-03/27/content_37930371.htm'");
L.push(")");
L.push("$out = Join-Path $env:TEMP 'ofm-raw.bin'");
L.push("foreach ($u in $urls) {");
L.push(" try {");
L.push(" Invoke-WebRequest -Uri $u -Proxy 'http://127.0.0.1:7897' -UserAgent $ua -TimeoutSec 45 -OutFile $out -ErrorAction Stop");
L.push(" $bytes = [System.IO.File]::ReadAllBytes($out)");
L.push(" $gb = [System.Text.Encoding]::GetEncoding(936)");
L.push(" $html = $gb.GetString($bytes)");
L.push(" $t = $html -replace '<script[\\s\\S]*?</script>',' ' -replace '<style[\\s\\S]*?</style>',' ' -replace '<[^>]+>',' '");
L.push(" $t = $t -replace '&nbsp;',' ' -replace '&amp;','&' -replace '\\s+',' '");
L.push(" Write-Output ('===== ' + $u + ' len=' + $t.Length)");
L.push(" Write-Output $t.Substring(0, [Math]::Min(3800, $t.Length))");
L.push(" } catch { Write-Output ('===== ' + $u + ' FAIL ' + $_.Exception.Message.Split([Environment]::NewLine)[0]) }");
L.push("}");
const ps = L.join("\n");
const b64 = Buffer.from(ps, "utf16le").toString("base64");
const r = await tools.pwsh({ command: "powershell -ExecutionPolicy Bypass -EncodedCommand " + b64, description: "Fetch GBK articles via encoded command", timeoutMs: 260000 });
const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "") : JSON.stringify(x);
console.log(t(r).slice(0, 12000));
